"""Build one offline Inspector from real canonical plan/report/PNG bytes."""
import argparse
import base64
import json
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument("--plan", type=Path, required=True)
parser.add_argument("--report", type=Path, required=True)
parser.add_argument("--image", type=Path, required=True)
parser.add_argument("--output", type=Path, required=True)
args = parser.parse_args()
plan_bytes, report_bytes, image_bytes = args.plan.read_bytes(), args.report.read_bytes(), args.image.read_bytes()
plan, report = json.loads(plan_bytes), json.loads(report_bytes)
if plan.get("plan_identity") != report.get("plan_identity") or plan.get("git_sha") != report.get("git_sha"):
    raise SystemExit("plan/report provenance mismatch")
if not plan.get("source_clean") or not report.get("source_clean") or image_bytes[:8] != b"\x89PNG\r\n\x1a\n":
    raise SystemExit("inspector inputs must be clean provenance and a PNG")

template = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>FrameGraphLab Inspector</title><style>
:root{color-scheme:dark;--bg:#071018;--card:#0d1b27;--card2:#102332;--line:#203b4d;--text:#e9f7ff;--muted:#8ca9b8;--cyan:#22d3ee;--pink:#f43f9f;--amber:#f5b942;--green:#5ee49b;--radius:14px}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;overflow-x:hidden;background:radial-gradient(circle at 80% -10%,#17304a 0,transparent 38%),var(--bg);color:var(--text);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}
button{font:inherit;color:inherit}.top{padding:26px clamp(16px,4vw,54px) 22px;border-bottom:1px solid var(--line);background:#08131ed9;backdrop-filter:blur(18px)}.eyebrow{color:var(--cyan);font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.top h1{font-size:clamp(27px,4vw,46px);line-height:1.04;letter-spacing:-.035em;margin:8px 0}.lede{max-width:780px;color:var(--muted);font-size:15px}.chips,.order-strip{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.chip{border:1px solid var(--line);border-radius:999px;padding:5px 9px;background:#0b1c29;color:#bceeff;font:12px ui-monospace,SFMono-Regular,Consolas,monospace}.shell{display:grid;grid-template-columns:280px minmax(0,1fr);gap:18px;padding:18px clamp(12px,3vw,38px) 42px;max-width:1680px;margin:auto;min-width:0}.sidebar{display:grid;align-content:start;gap:14px}.content{display:grid;gap:14px;min-width:0}.panel{background:linear-gradient(155deg,#102432e8,#0b1721f2);border:1px solid #1c394b;border-radius:var(--radius);box-shadow:0 16px 50px #0005;padding:17px;min-width:0}.panel h2{font-size:14px;margin:0 0 12px;letter-spacing:.02em}.panel h3{font-size:12px;color:var(--muted);margin:13px 0 6px}.muted{color:var(--muted)}.big{font-size:28px;font-weight:760;letter-spacing:-.04em}.metric-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.metric{padding:10px;background:#09151f;border:1px solid var(--line);border-radius:10px}.metric b{display:block;font-size:16px}.metric small{color:var(--muted)}.capture{width:100%;display:block;border-radius:10px;border:1px solid var(--line);background:#000}.scroll{overflow:auto;max-width:100%;padding-bottom:3px}.dag{height:146px;position:relative;min-width:720px}.dag svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}.pass-node{position:absolute;width:128px;min-height:53px;border:1px solid #2b5368;border-radius:10px;background:#0b1c28;text-align:left;padding:8px;cursor:pointer;transition:border-color .14s,transform .14s,background .14s}.pass-node:hover,.pass-node.selected{border-color:var(--cyan);background:#123044;transform:translateY(-2px)}.pass-node.dim{opacity:.35}.pass-node .index{color:var(--pink);font:800 10px ui-monospace,monospace}.pass-node .name{font-weight:700;font-size:12px;overflow-wrap:anywhere}.split{display:grid;grid-template-columns:1.35fr .65fr;gap:14px;min-width:0}.resource-row{display:grid;grid-template-columns:150px minmax(210px,1fr) 118px;gap:10px;align-items:center;padding:7px;border-radius:9px;border:1px solid transparent}.resource-row.selected,.resource-row.linked{background:#112b39;border-color:#27586e}.resource-button{border:0;background:transparent;text-align:left;padding:0;cursor:pointer;font-weight:700;overflow-wrap:anywhere}.lifetime{height:17px;position:relative;background:#08131d;border:1px solid #193548;border-radius:5px;overflow:hidden}.life-bar{height:100%;position:absolute;background:linear-gradient(90deg,var(--cyan),var(--pink));opacity:.82;border-radius:4px}.range{font:11px ui-monospace,monospace;color:var(--muted)}.heap-track{min-width:720px;height:44px;position:relative;background:#07131d;border:1px solid #19384a;border-radius:8px;margin:7px 0 18px}.allocation{position:absolute;top:5px;height:32px;min-width:3px;border:1px solid #59dff4;background:#157795aa;border-radius:5px;color:white;font:10px ui-monospace,monospace;overflow:hidden;cursor:pointer;padding:3px}.allocation.alias{border-color:var(--pink);background:#9e246eaa}.table{display:grid;gap:5px}.row{display:grid;grid-template-columns:155px 84px minmax(190px,1fr);gap:10px;padding:7px 8px;background:#091620;border-radius:7px;font-size:12px}.row.dim{display:none}.kind{font:700 10px ui-monospace,monospace;color:var(--amber)}.timing{display:grid;grid-template-columns:160px minmax(170px,1fr) 110px;gap:10px;align-items:center;margin:7px 0}.timing.dim{opacity:.3}.timing-bar{height:9px;background:#08131d;border-radius:5px;overflow:hidden}.timing-bar span{display:block;height:100%;background:linear-gradient(90deg,var(--pink),var(--cyan));border-radius:5px}.memory-bars{display:grid;gap:9px}.memory-line{display:grid;grid-template-columns:94px 1fr 92px;gap:8px;align-items:center}.memory-track{height:10px;background:#07131d;border-radius:6px;overflow:hidden}.memory-track span{display:block;height:100%;border-radius:6px;background:var(--cyan)}.memory-line:nth-child(2) span{background:var(--pink)}.memory-line:nth-child(3) span{background:var(--green)}.selected-copy{min-height:68px;white-space:pre-wrap;overflow-wrap:anywhere}.empty{padding:11px;border:1px dashed #315064;border-radius:8px;color:var(--muted)}:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}
@media (max-width: 980px){.shell{grid-template-columns:220px minmax(0,1fr)}.split{grid-template-columns:1fr}.resource-row{grid-template-columns:120px minmax(190px,1fr) 95px}}
@media (max-width: 700px){.top{padding:20px 15px}.shell{display:block;padding:12px}.sidebar,.content{display:grid;gap:12px}.sidebar{margin-bottom:12px}.split{display:grid}.panel{padding:14px}.resource-row{grid-template-columns:105px minmax(170px,1fr) 78px}.row{grid-template-columns:120px 65px minmax(170px,1fr)}.timing{grid-template-columns:125px minmax(150px,1fr) 90px}.capture{max-height:260px;object-fit:cover}.top h1{font-size:30px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
</style></head><body>
<header class="top"><div class="eyebrow">FrameGraphLab / canonical execution evidence</div><h1>Neon Ruins frame graph</h1><div class="lede">One deterministic Core plan, actual Direct3D 12 placed heaps, explicit barriers, local GPU timing and the captured frame that produced this report.</div><div class="chips" id="header-chips"></div></header>
<main class="shell"><aside class="sidebar">
<section class="panel"><h2>Frame provenance</h2><div class="big" id="identity"></div><div class="muted" id="provenance"></div></section>
<section class="panel" id="memory-panel"><h2>Transient memory</h2><div class="memory-bars" id="memory-bars"></div><h3>Savings</h3><div class="big" id="saving"></div><div class="muted" id="memory-copy"></div></section>
<section class="panel"><h2>Captured output</h2><img id="capture-preview" class="capture" alt="Procedural Neon Ruins capture"><div class="muted" id="pixel-copy"></div></section>
<section class="panel"><h2 id="selected-pass">Selected pass</h2><div class="selected-copy muted" id="selected-copy">Choose a pass or resource.</div></section>
</aside><div class="content">
<section class="panel" id="dag-panel"><h2>Pass DAG & stable execution order</h2><div class="scroll"><div class="dag" id="dag"></div></div><div class="order-strip" id="order-strip"></div></section>
<section class="split"><div class="panel" id="lifetime-panel"><h2>Resource lifetimes</h2><div class="scroll" id="lifetimes"></div></div><div class="panel" id="culled-panel"><h2>Culled passes</h2><div id="culled"></div></div></section>
<section class="panel" id="heap-panel"><h2>Physical heaps & alias regions</h2><div class="scroll" id="heaps"></div><div id="alias-copy" class="muted"></div></section>
<section class="panel" id="barrier-panel"><h2>Transition / UAV / alias barriers</h2><div class="chips" id="barrier-summary"></div><div class="scroll"><div class="table" id="barriers"></div></div></section>
<section class="panel" id="timing-panel"><h2>Per-pass GPU and CPU record time</h2><div id="timings"></div><div class="muted">Local observation; no cross-machine SLA.</div></section>
</div></main><script>
const PLAN_DATA = '__PLAN__';
const REPORT_DATA = '__REPORT__';
const IMAGE_DATA = '__IMAGE__';
const decode = value => JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(value), c => c.charCodeAt(0))));
const plan=decode(PLAN_DATA), report=decode(REPORT_DATA), passById=new Map(plan.passes.map(p=>[p.id,p]));
const formatNames=['RGBA8','RGBA16F','D32F'], accessNames=['Read','Write','ReadWrite'];
const usageNames=['ShaderRead','RenderTarget','DepthWrite','DepthRead','UAV','CopySource','CopyDest','Present'];
const stateNames=['Common','ShaderRead','RenderTarget','DepthWrite','DepthRead','UAV','CopySource','CopyDest','Present'];
const kindNames=['Transition','UAV','Aliasing'], hazardNames=['RAW','WAR','WAW','Explicit'];
const $=id=>document.getElementById(id), node=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
const bytes=value=>value>=1048576?(value/1048576).toFixed(2)+' MiB':value>=1024?(value/1024).toFixed(1)+' KiB':value+' B';
const chip=text=>node('span','chip',text);
$('identity').textContent=plan.plan_identity;
$('provenance').textContent=`${report.backend} · ${report.adapter}\n${report.git_sha.slice(0,12)} · clean=${report.source_clean}`;
['schema '+plan.schema_version, `${plan.order.length} active passes`, `${plan.resources.length} resources`, `${plan.dependencies.length} dependency edges`, `seed ${plan.scene_seed}`].forEach(x=>$('header-chips').append(chip(x)));
$('capture-preview').src='data:image/png;base64,'+IMAGE_DATA;
$('pixel-copy').textContent=`${report.width}×${report.height} · pixel ${report.pixel_hash} · ${(report.non_black_fraction*100).toFixed(1)}% nonblack · ${report.color_buckets} color buckets`;
const memoryMax=Math.max(report.logical_bytes,report.committed_bytes,report.actual_heap_bytes);
[['Logical',report.logical_bytes],['Reference',report.committed_bytes],['Physical',report.actual_heap_bytes]].forEach(([name,value])=>{const row=node('div','memory-line');row.append(node('span','',name));const track=node('div','memory-track'),bar=node('span');bar.style.width=(value/memoryMax*100)+'%';track.append(bar);row.append(track,node('b','',bytes(value)));$('memory-bars').append(row)});
const saving=report.committed_bytes?report.saved_bytes/report.committed_bytes*100:0;$('saving').textContent=saving.toFixed(1)+'%';$('memory-copy').textContent=`${bytes(report.saved_bytes)} saved · ${report.heap_count} heap · ${report.alias_reuse_events} reuse events\nActual ${bytes(report.actual_heap_bytes)} = planned ${bytes(report.planned_heap_bytes)}`;
const dag=$('dag'), dagWidth=Math.max(720,plan.order.length*148);dag.style.width=dagWidth+'px';
const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox',`0 0 ${dagWidth} 146`);svg.innerHTML='<defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 L7 3.5 L0 7z" fill="#3c819c"/></marker></defs>';dag.append(svg);
const positions=new Map(plan.order.map((id,index)=>[id,{x:10+index*148,y:65}]));
for(const edge of plan.dependencies){const a=positions.get(edge.before),b=positions.get(edge.after);if(!a||!b)continue;const path=document.createElementNS(svg.namespaceURI,'path'),arch=Math.max(15,(b.x-a.x)*.16);path.setAttribute('d',`M${a.x+128},${a.y+27} C${a.x+128+arch},${a.y-arch} ${b.x-arch},${b.y-arch} ${b.x},${b.y+27}`);path.setAttribute('fill','none');path.setAttribute('stroke',edge.hazard===3?'#f5b942':'#2e7893');path.setAttribute('stroke-width','1.4');path.setAttribute('marker-end','url(#arrow)');svg.append(path)}
const passNodes=new Map();
plan.order.forEach((id,index)=>{const p=passById.get(id),button=node('button','pass-node');button.style.left=(10+index*148)+'px';button.style.top='65px';button.dataset.pass=id;button.append(node('div','index',`#${index} · P${id}`),node('div','name',p.name));button.addEventListener('click',()=>selectPass(id));dag.append(button);passNodes.set(id,button);$('order-strip').append(chip(`${index} · ${p.name}`))});
const resourceRows=new Map(), activeCount=Math.max(1,plan.order.length);
for(const resource of plan.resources){const row=node('div','resource-row');row.dataset.resource=resource.id;const button=node('button','resource-button',resource.name);button.addEventListener('click',()=>selectResource(resource.id));row.append(button);const track=node('div','lifetime');if(resource.lifetime){const bar=node('span','life-bar');bar.style.left=(resource.lifetime.first/activeCount*100)+'%';bar.style.width=((resource.lifetime.last-resource.lifetime.first+1)/activeCount*100)+'%';track.append(bar)}row.append(track,node('span','range',resource.lifetime?`${resource.lifetime.first}…${resource.lifetime.last}`:'not live'));$('lifetimes').append(row);resourceRows.set(resource.id,row)}
if(plan.culled.length){for(const id of plan.culled)$('culled').append(chip(passById.get(id)?.name||`Pass ${id}`))}else $('culled').append(node('div','empty','No culled passes in this exported scene.'));
const allocations=plan.allocation.resources.filter(Boolean), byHeap=Map.groupBy(allocations,a=>a.heap);
for(const heap of plan.allocation.heaps){$('heaps').append(node('h3','',`Heap ${heap.id} · class ${heap.class} · ${bytes(heap.bytes)}`));const track=node('div','heap-track');for(const a of byHeap.get(heap.id)||[]){const segment=node('button','allocation'+(a.reused_region?' alias':''),`R${a.resource} @${a.offset}`);segment.style.left=(a.offset/heap.bytes*100)+'%';segment.style.width=Math.max(2,a.size/heap.bytes*100)+'%';segment.addEventListener('click',()=>selectResource(a.resource));track.append(segment)}$('heaps').append(track)}
$('alias-copy').textContent=plan.allocation.aliases.length?plan.allocation.aliases.map(a=>`R${a.before} → R${a.after} at pass ${a.position}, heap ${a.heap}, offset ${a.offset}`).join(' · '):'Aliasing disabled: no reuse chain.';
[['Transitions',plan.barriers.transition_count],['UAV',plan.barriers.uav_count],['Activations',plan.barriers.aliasing_count]].forEach(x=>$('barrier-summary').append(chip(x[0]+' '+x[1])));
const barrierRows=[];plan.barriers.passes.forEach((entry,position)=>{for(const phase of ['before','after'])for(const b of entry[phase])barrierRows.push({position,phase,...b})});for(const b of plan.barriers.final)barrierRows.push({position:plan.order.length,phase:'final',...b});
for(const b of barrierRows){const row=node('div','row');row.dataset.pass=b.position<plan.order.length?plan.order[b.position]:'';const passName=b.position<plan.order.length?passById.get(plan.order[b.position]).name:'Graph final';row.append(node('span','',passName+' · '+b.phase),node('span','kind',kindNames[b.kind]),node('span','',b.kind===0?`R${b.resource} ${stateNames[b.before]} → ${stateNames[b.after]}`:`R${b.alias_before??'*'} → R${b.resource}`));$('barriers').append(row)}
const maxGpu=Math.max(.000001,...report.pass_timings.map(t=>t.gpu_ms));
for(const [index,t] of report.pass_timings.entries()){const row=node('div','timing');row.dataset.pass=plan.order[index];row.append(node('span','',t.name));const track=node('div','timing-bar'),bar=node('span');bar.style.width=(t.gpu_ms/maxGpu*100)+'%';track.append(bar);row.append(track,node('span','range',`${t.gpu_ms.toFixed(4)} ms GPU\n${t.cpu_record_ms.toFixed(4)} CPU`));$('timings').append(row)}
function selectPass(id){const pass=passById.get(id),used=new Set(pass.usages.map(u=>u.resource));for(const [pid,n] of passNodes)n.classList.toggle('selected',pid===id);for(const [rid,r] of resourceRows){r.classList.toggle('linked',used.has(rid));r.classList.remove('selected')}for(const r of document.querySelectorAll('#barriers .row'))r.classList.toggle('dim',Number(r.dataset.pass)!==id);for(const r of document.querySelectorAll('.timing'))r.classList.toggle('dim',Number(r.dataset.pass)!==id);$('selected-pass').textContent=pass.name;$('selected-copy').textContent=pass.usages.length?pass.usages.map(u=>`${plan.resources[u.resource].name}: ${accessNames[u.access]} / ${usageNames[u.usage]}`).join('\n'):'No resource usages';window.__FGL_STATE__={selectedPass:id,selectedResource:null}}
function selectResource(id){const resource=plan.resources[id];for(const [rid,r] of resourceRows){r.classList.toggle('selected',rid===id);r.classList.toggle('linked',false)}for(const [pid,n] of passNodes){const used=passById.get(pid).usages.some(u=>u.resource===id);n.classList.toggle('selected',used);n.classList.toggle('dim',!used)}for(const r of document.querySelectorAll('#barriers .row'))r.classList.toggle('dim',!r.textContent.includes(`R${id}`));for(const r of document.querySelectorAll('.timing'))r.classList.remove('dim');const a=plan.allocation.resources[id];$('selected-pass').textContent=resource.name;$('selected-copy').textContent=`${resource.kind} ${resource.kind==='texture'?resource.width+'×'+resource.height+' '+formatNames[resource.format]:bytes(resource.bytes)}\nLifetime ${resource.lifetime?resource.lifetime.first+'…'+resource.lifetime.last:'none'}${a?'\nHeap '+a.heap+' · offset '+a.offset+' · '+bytes(a.size)+(a.reused_region?' · reused':''):''}`;window.__FGL_STATE__={selectedPass:null,selectedResource:id}}
document.addEventListener('keydown',event=>{if(event.key==='Escape')selectPass(plan.order[0])});selectPass(plan.order[0]);window.__FGL_INSPECTOR_READY__=true;
</script></body></html>'''
html = template.replace("__PLAN__", base64.b64encode(plan_bytes).decode()).replace("__REPORT__", base64.b64encode(report_bytes).decode()).replace("__IMAGE__", base64.b64encode(image_bytes).decode())
args.output.parent.mkdir(parents=True, exist_ok=True)
temporary = args.output.with_suffix(args.output.suffix + ".tmp")
temporary.write_text(html, encoding="utf-8")
temporary.replace(args.output)
print(json.dumps({"output": str(args.output), "bytes": len(html), "plan_identity": plan["plan_identity"]}))
